316	        }
317	        audit.recordChangeOnCommit(sheetId, user, line);
318	        if (next == ClaimStatus.SETTLED) {
319	            watches.notifyWatchers(sheetId, user, person, number);
320	        }
321	        rollup.recordChanges(sheetId, user, before);
322	        return changed;
323	    }
324	
325	    /** Settle every claim given, one at a time in the order given, by exactly the rules of settling one claim (a
326	     *  claim a clerk's limit makes PENDING counts as settled), as the sheet's next settle batch, each keeping its
327	     *  number; after the claims' own lines BATCH_SETTLED is recorded with the batch's count and the frozen figures
328	     *  of those SETTLED added up. All or nothing: when any claim cannot be settled, none is, nothing is written and
329	     *  null is returned. The claims, as saved, in the order given; none when none is given. */
330	    @Transactional
331	    public List<Claim> settleBatch(String sheetId, String user, List<Long> ids) {
332	        if (ids.isEmpty()) {
333	            return List.of();
334	        }
335	        for (long id : ids) {
336	            try {
337	                changeStatus(sheetId, user, id, ClaimStatus.SETTLED);
338	            } catch (ResponseStatusException refusal) {
339	                TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
340	                return null;
341	            }
342	        }
343	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
344	        int batch = sheet.nextSettleBatch();
345	        sheetStore.saveAndFlush(sheet);
346	        List<Claim> marked = ids.stream().map(id -> {
347	            Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
348	            claim.setSettleBatch(batch);
349	            return claims.saveAndFlush(claim);
350	        }).toList();
351	        BigDecimal total = marked.stream()
352	                .filter(claim -> claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null)
353	                .map(Claim::getSettledDue)
354	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
355	        audit.recordChangeOnCommit(sheetId, user, "BATCH_SETTLED sheet=" + sheetId + " by=" + user + " batch=" + batch
356	                + " count=" + marked.size() + " total=" + total.toPlainString());
357	        return marked;
358	    }
359	
360	    /** Defer an OPEN claim until a day after the sheet's today: until the sheet's today reaches that day it counts
361	     *  in no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim that
362	     *  is not OPEN, a day not after today and a claim due by inside a closed period. */
363	    @Transactional
364	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
365	        sheets.load(sheetId, user);
366	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
367	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
368	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
369	        refuseIfClosed(sheetId, claim.getDueBy());
370	        if (claim.getStatus() != ClaimStatus.OPEN) {
371	            throw new ResponseStatusException(HttpStatus.CONFLICT,
372	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
373	        }
374	        if (!until.isAfter(sheet.getToday())) {
375	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A claim is deferred to a day after today");
376	        }
377	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
378	        Rollup.Figures before = rollup.of(sheetId);
379	        claim.setDeferredUntil(until);
380	        Claim deferred = claims.saveAndFlush(claim);
381	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_DEFERRED", user, person, deferred, deferred.getNumber()) + " until=" + until);
382	        rollup.recordChanges(sheetId, user, before);
383	        return deferred;
384	    }
385	
386	    /** A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed, and with it its period and its
387	     *  number, and a figure a statement binds it to stays bound. Refused for anyone but a steward, a claim in any
388	     *  other status, a claim due by inside a closed period and a new date after its person retired. */
389	    @Transactional
390	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
391	        sheets.load(sheetId, user);
392	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
393	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
394	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
395	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
396	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim");
397	        }
398	        if (!claim.getStatus().isOpen()) {
399	            throw new ResponseStatusException(HttpStatus.CONFLICT,
400	                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can");
401	        }
402	        refuseIfClosed(sheetId, claim.getDueBy());
403	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
404	        refuseIfRetired(person, date);
405	        Rollup.Figures before = rollup.of(sheetId);
406	        LocalDate old = claim.getDate();
407	        claim.setDate(date);
408	        Claim redated = claims.saveAndFlush(claim);
409	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_REDATED", user, person, redated, redated.getNumber())
410	                + " old=" + old + " new=" + date);
411	        rollup.recordChanges(sheetId, user, before);
412	        return redated;
413	    }
414	
415	    /** Open a claim's editor for this user, locking the claim for other users until they save or cancel it or the
416	     *  sheet's today changes. Refused for a claim that is not a draft, one due by inside a closed period and one
417	     *  another user has locked; a refused claim takes no lock. Opening it again for the same user keeps the lock. */
418	    @Transactional
419	    public Claim lock(String sheetId, String user, long id) {
420	        sheets.load(sheetId, user);
421	        sheetStore.findLockedById(sheetId).orElseThrow();
422	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
423	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
424	        if (claim.getStatus() != ClaimStatus.DRAFT) {
425	            throw new ResponseStatusException(HttpStatus.CONFLICT,
426	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
427	        }
428	        refuseIfClosed(sheetId, claim.getDueBy());
429	        refuseIfLockedByOther(claim, user);
430	        claim.setLockedBy(user);
431	        return claims.saveAndFlush(claim);
432	    }
433	
434	    /** Cancel this user's claim editor, releasing their lock on the claim; another user's lock is left as it is. */
435	    @Transactional
436	    public Claim unlock(String sheetId, String user, long id) {
437	        sheets.load(sheetId, user);
438	        sheetStore.findLockedById(sheetId).orElseThrow();
439	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
440	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
441	        if (user.equals(claim.getLockedBy())) {
442	            claim.setLockedBy(null);
443	            claim = claims.saveAndFlush(claim);
444	        }
445	        return claim;
446	    }
447	
448	    /** Refuse a change to a claim while another user has its editor open. */
449	    private static void refuseIfLockedByOther(Claim claim, String user) {
450	        if (claim.getLockedBy() != null && !claim.getLockedBy().equals(user)) {
451	            throw new ResponseStatusException(HttpStatus.CONFLICT,
452	                    "That claim is being edited by " + claim.getLockedBy());
453	        }
454	    }
455	
456	    /** Raise a claim's proofs count by one. Refused for a SETTLED or VOID claim and one due by inside a closed
457	     *  period. */
458	    @Transactional
459	    public Claim addProof(String sheetId, String user, long id) {
460	        sheets.load(sheetId, user);
461	        sheetStore.findLockedById(sheetId).orElseThrow();
462	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
463	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
464	        refuseIfClosed(sheetId, claim.getDueBy());
465	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
466	                || claim.getStatus() == ClaimStatus.DELETED) {
467	            throw new ResponseStatusException(HttpStatus.CONFLICT,
468	                    "A " + claim.getStatus() + " claim cannot be given a proof");
469	        }
470	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
471	        claim.addProof();
472	        Claim proven = claims.saveAndFlush(claim);
473	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_PROOF_ADDED", user, person, proven, proven.getNumber())
474	                + " proofs=" + proven.getProofs());
475	        return proven;
476	    }
477	
478	    /** Comment on a claim, as this user on the sheet's today. Refused for an empty comment. */
479	    @Transactional
480	    public Claim comment(String sheetId, String user, long id, String text) {
481	        sheets.load(sheetId, user);
482	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
483	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
484	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
485	        String trimmed = text == null ? "" : text.trim();
486	        if (trimmed.isEmpty()) {
487	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A comment cannot be empty");
488	        }
489	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
490	        claim.comment(user, sheet.getToday(), trimmed);
491	        Claim commented = claims.saveAndFlush(claim);
492	        audit.recordChangeOnCommit(sheetId, user, entry("COMMENT_ADDED", user, person, commented,
493	                commented.getNumber()) + " text=" + trimmed);
494	        return commented;
495	    }
496	
497	    /** Write a reminder for an OPEN or PENDING claim, dated the sheet's today. Refused for a claim in any other
498	     *  status and one already reminded on the sheet's today. */
499	    @Transactional
500	    public Claim remind(String sheetId, String user, long id) {
501	        sheets.load(sheetId, user);
502	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
503	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
504	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
505	        if (!claim.getStatus().isOpen()) {
506	            throw new ResponseStatusException(HttpStatus.CONFLICT,
507	                    "A " + claim.getStatus() + " claim cannot be reminded; only an OPEN or PENDING one can");
508	        }
509	        if (sheet.getToday().equals(claim.getRemindedOn())) {
510	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today");
511	        }
512	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
513	        claim.remind(sheet.getToday());
514	        Claim reminded = claims.saveAndFlush(claim);
515	        audit.recordChangeOnCommit(sheetId, user, entry("REMIND", user, person, reminded, reminded.getNumber()));
516	        return reminded;
517	    }
518	
519	    /** A steward approves a PENDING claim: it becomes SETTLED, its due fixed as it is at this moment (its live
520	     *  figure with the late charge it has gained). Refused for a clerk, for the user who opened the claim or last edited it, for a
521	     *  claim that is not PENDING and for one due by inside a closed period. */
522	    @Transactional
523	    public Claim approve(String sheetId, String user, long id) {
524	        sheets.load(sheetId, user);
525	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
526	        Claim claim = pendingClaim(sheetId, user, id);
527	        if (claim.isOpenedOrEditedBy(user)) {
528	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
529	                    "The user who opened or last edited a claim cannot approve it");
530	        }
531	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
532	        BigDecimal due = dueNow(sheet, claim, person);
533	        refuseUnproven(sheet, claim, person, due);
534	        Rollup.Figures before = rollup.of(sheetId);
535	        claim.setStatus(ClaimStatus.SETTLED);
536	        claim.setSettledDue(due);
537	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
538	        Claim changed = claims.saveAndFlush(claim);
539	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_APPROVED", user, person, changed, changed.getNumber())
540	                + " due=" + dueText(changed));
541	        watches.notifyWatchers(sheetId, user, person, changed.getNumber());
542	        rollup.recordChanges(sheetId, user, before);
543	        return changed;
544	    }
545	
546	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by its person's last
547	     *  statement if that statement included it. Refused for a clerk, for a claim that is not PENDING and for one
548	     *  due by inside a closed period. */
549	    @Transactional
550	    public Claim reject(String sheetId, String user, long id, String reason) {
551	        sheets.load(sheetId, user);
552	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
553	        Claim claim = pendingClaim(sheetId, user, id);
554	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
555	        Rollup.Figures before = rollup.of(sheetId);
556	        claim.setStatus(ClaimStatus.OPEN);
557	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
558	        Claim changed = claims.saveAndFlush(claim);
559	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_REJECTED", user, person, changed, changed.getNumber())
560	                + " reason=" + reason.trim());
561	        rollup.recordChanges(sheetId, user, before);
562	        return changed;
563	    }
564	
565	    /** A steward re-settles a SETTLED claim: its due is fixed again at the figure it would have today as an open
566	     *  claim bound by no statement (its live figure at today's rates, grades and floor, with the late charge it
567	     *  would have gained by today on top), and its status log gains a SETTLED line. Refused for a clerk, for a
568	     *  claim that is not SETTLED and for one due by inside a closed period. */
569	    @Transactional

