          @if (voidReasons.all().length > 0) {
            <label [for]="'claim-void-reason-' + c.id">Reason to void</label>
            <select [id]="'claim-void-reason-' + c.id" data-testid="claim-void-reason"
                    [value]="chosenVoidReasons()[c.id] ?? ''" (change)="voidReasonChanged(c, $any($event.target).value)">
              <option value="">Choose a reason</option>
              @for (r of voidReasons.all(); track r.id) {
                <option [value]="r.reason">{{ r.reason }}</option>
              }
            </select>
          }
          <button type="button" data-testid="claim-void" (click)="changeStatus(c, 'VOID')"
                  [attr.aria-label]="'Void claim of ' + c.amount + ' on ' + c.date">Void</button>
          <button type="button" data-testid="claim-delete" (click)="changeStatus(c, 'DELETED')"
                  [attr.aria-label]="'Delete claim of ' + c.amount + ' on ' + c.date">Delete</button>
          <button type="button" data-testid="claim-restore" (click)="changeStatus(c, 'DRAFT')"
                  [attr.aria-label]="'Restore claim of ' + c.amount + ' on ' + c.date">Restore</button>
          <label [for]="'claim-reassign-to-' + c.id">Move to</label>
          <select [id]="'claim-reassign-to-' + c.id" data-testid="claim-reassign-to"
                  [value]="reassignTo()[c.id] ?? ''" (change)="reassignToChanged(c, $any($event.target).value)">
            <option value="">Choose a person</option>
            @for (o of others(); track o.id) {
              <option [value]="o.id">{{ o.name }}</option>
            }
          </select>
          <button type="button" data-testid="claim-reassign" (click)="reassign(c)"
                  [attr.aria-label]="'Move claim of ' + c.amount + ' on ' + c.date + ' to another person'">Move</button>
          <label [for]="'claim-inline-amount-' + c.id">New amount</label>
          <input [id]="'claim-inline-amount-' + c.id" data-testid="claim-inline-amount" inputmode="decimal"
                 autocomplete="off" [value]="inlineAmounts()[c.id] ?? ''"
                 (input)="inlineAmountChanged(c, $any($event.target).value)" />
          <button type="button" data-testid="claim-inline-save" (click)="saveInline(c)"
                  [attr.aria-label]="'Save the amount of claim of ' + c.amount + ' on ' + c.date">Save amount</button>
          @if (editingId() === c.id) {
            <button type="button" data-testid="claim-cancel" (click)="cancel()">Cancel</button>
          } @else {
            <button type="button" data-testid="claim-edit" (click)="edit(c)"
                    [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date">Edit</button>
          }
          <ol [attr.aria-label]="'Status log of claim of ' + c.amount + ' on ' + c.date">
            @for (l of c.log; track $index) {
              <li data-testid="claim-log-line">{{ l.status }} by {{ l.by }} on {{ l.on }} due={{ l.due ?? notAvailable }}</li>
            }
          </ol>
          <ol [attr.aria-label]="'Comments on claim of ' + c.amount + ' on ' + c.date">
            @for (m of c.comments ?? []; track $index) {
              <li data-testid="claim-comments-line">{{ m.by }} on {{ m.on }}: {{ m.text }}</li>
